declare(strict_types=1);require __DIR__.'/functions.php';$clientId=getenv('GOOGLE_CLIENT_ID')?:'';$appUrl=rtrim(getenv('APP_URL')?:'https://bingkaiin.apinsdigital.my.id','/');if($clientId===''){flash('error','Login Google belum dikonfigurasi oleh administrator.');redirect('login');}if(session_status()!==PHP_SESSION_ACTIVE)session_start();$_SESSION['google_oauth_state']=bin2hex(random_bytes(24));$params=['client_id'=>$clientId,'redirect_uri'=>$appUrl.'/google/callback','response_type'=>'code','scope'=>'openid email profile','state'=>$_SESSION['google_oauth_state'],'prompt'=>'select_account'];header('Location: https://accounts.google.com/o/oauth2/v2/auth?'.http_build_query($params));exit;
